import { agent_tool_handler_result, agent_tool_postcondition } from "std/agent/tool_lifecycle"
import { replace_text } from "std/fs"
import { ToolRegistry } from "std/tools"

type Input = {resource: string, string_field: string, integer_field: string, boolean_field: string}

type File = {path: string, content: string}

pub fn identifier(value: string) -> bool {
  if value == "" {
    return false
  }
  const alphabet = "abcdefghijklmnopqrstuvwxyz"
  const rest = "abcdefghijklmnopqrstuvwxyz_0123456789"
  let first = true
  for char in chars(value) {
    if first {
      if !alphabet.contains(char) {
        return false
      }
      first = false
    }
    if !rest.contains(char) {
      return false
    }
  }
  return value != "id"
}

pub fn render(input: Input) -> list<File> {
  require identifier(input.resource),
    "resource must start with a lowercase letter and contain only lowercase letters, digits or underscores"
  for field in [input.string_field, input.integer_field, input.boolean_field] {
    require identifier(field), "invalid field name or reserved id"
  }
  require input.string_field != input.integer_field && input.string_field != input.boolean_field
    && input.integer_field != input.boolean_field,
    "fields must be distinct"
  const r = input.resource
  const s = input.string_field
  const i = input.integer_field
  const b = input.boolean_field
  const module =
    "from threading import Lock\n\n\ndef mount(app):\n    records = []\n    lock = Lock()\n    fields = {\"${s}\": str, \"${i}\": int, \"${b}\": bool}\n\n    def create(payload):\n        if payload.keys() != fields.keys() or any(\n            type(payload[name]) is not expected for name, expected in fields.items()\n        ):\n            return 400, {\"error\": \"invalid_fields\"}\n        with lock:\n            record = {**payload, \"id\": len(records) + 1}\n            records.append(record)\n            return 201, record.copy()\n\n    def list_records(payload):\n        with lock:\n            return 200, [record.copy() for record in records]\n\n    app.route(\"POST\", \"/api/${r}\", create)\n    app.route(\"GET\", \"/api/${r}\", list_records)\n"
  const tests =
    "import unittest\nfrom app.http import App\n\n\nclass ResourceTest(unittest.TestCase):\n    def test_contract(self):\n        app = App()\n        path = \"/api/${r}\"\n        payload = {\"${s}\": \"example\", \"${i}\": 2, \"${b}\": True}\n        self.assertEqual(app.dispatch(\"GET\", path), (200, []))\n        invalid = [None, {}, {**payload, \"id\": 9}, [], \"x\", 1, True]\n        for field in payload:\n            invalid.append({k: v for k, v in payload.items() if k != field})\n        for field, values in {\"${s}\": [None, 1, True, [], {}], \"${i}\": [None, True, False, 1.5, \"2\", [], {}], \"${b}\": [None, 0, 1, \"true\", [], {}]}.items():\n            invalid.extend({**payload, field: v} for v in values)\n        for bad in invalid:\n            with self.subTest(payload=bad):\n                self.assertEqual(app.dispatch(\"POST\", path, bad)[0], 400)\n                self.assertEqual(app.dispatch(\"GET\", path), (200, []))\n        one = {**payload, \"id\": 1}\n        self.assertEqual(app.dispatch(\"POST\", path, payload), (201, one))\n        second = {\"${s}\": \"\", \"${i}\": -1, \"${b}\": False}\n        two = {**second, \"id\": 2}\n        self.assertEqual(app.dispatch(\"POST\", path, second), (201, two))\n        self.assertEqual(app.dispatch(\"GET\", path), (200, [one, two]))\n        for bad in invalid:\n            self.assertEqual(app.dispatch(\"POST\", path, bad)[0], 400)\n            self.assertEqual(app.dispatch(\"GET\", path), (200, [one, two]))\n        self.assertEqual(app.dispatch(\"POST\", path, payload), (201, {**payload, \"id\": 3}))\n        other = App()\n        self.assertEqual(other.dispatch(\"GET\", path), (200, []))\n        self.assertEqual(other.dispatch(\"POST\", path, payload), (201, one))\n        self.assertEqual(app.dispatch(\"GET\", path), (200, [one, two, {**payload, \"id\": 3}]))\n        self.assertEqual(app.dispatch(\"GET\", \"/health\"), (200, {\"status\": \"ok\"}))\n"
  const docs =
    "# ${r} API\n\nPOST /api/${r} requires exactly ${s} (string), ${i} (integer), ${b} (boolean). Booleans are not integers. Missing, extra, or wrong-typed fields return 400 without inserting or consuming an ID.\n\nRequest:\n```json\n{\"${s}\": \"example\", \"${i}\": 2, \"${b}\": true}\n```\n201 response:\n```json\n{\"${s}\": \"example\", \"${i}\": 2, \"${b}\": true, \"id\": 1}\n```\nInvalid request:\n```json\n{\"${s}\": \"example\", \"${i}\": true, \"${b}\": true}\n```\n400 response:\n```json\n{\"error\": \"invalid_fields\"}\n```\nGET /api/${r} returns 200 and records in insertion order:\n```json\n[{\"${s}\": \"example\", \"${i}\": 2, \"${b}\": true, \"id\": 1}]\n```\nStorage and sequential IDs are isolated per App instance and reset with it. The host automatically calls mount(app). /health is unchanged.\n\nRun `python3 -m unittest discover -s tests` before finishing.\n"
  return [
    {path: "app/resources/${r}.py", content: module},
    {path: "tests/test_${r}.py", content: tests},
    {path: "docs/${r}.md", content: docs},
  ]
}

pub fn prepare(fs: HarnessFs, root: string, input: Input) -> list<File> {
  const files = render(input)
  const host = fs.read_text(path_join(root, "app/http.py"))
  for marker in [
    "class App:",
    "def route(",
    "def dispatch(",
    "importlib.import_module(f\"app.resources.{source.stem}\").mount(self)",
    "return 200, {\"status\": \"ok\"}",
    "return handler({} if payload is None else payload)",
  ] {
    require host.contains(marker), "unsupported HTTP host"
  }
  require fs.read_text(path_join(root, "app/resources/__init__.py")).contains(
    "Resource modules export mount(app).",
  ),
    "unsupported resource contract"
  require fs.exists(path_join(root, "tests")), "tests directory is required"
  for file in files {
    require !fs.exists(path_join(root, file.path)), "target already exists: ${file.path}"
  }
  return files
}

pub fn tools(fs: HarnessFs, root: string, registry: ToolRegistry? = nil) -> ToolRegistry {
  let reg = registry ?? tool_registry()
  reg = tool_define(
    reg,
    "check_standard_resource",
    "Check supported inputs and current project preconditions without writes.",
    {
      inputSchema: schema_to_json_schema(schema_of(Input)) + {additionalProperties: false},
      annotations: {kind: "read", side_effect_level: "read_only", readOnlyHint: true},
      handler: { args ->
        const input: Input = schema_expect(args, schema_of(Input))
        const checked = try {
          prepare(fs, root, input)
        }
        const verdict = match checked {
          Ok(_files) -> { {kind: "ready"} }
          Err(error) -> { {kind: "declined", reason: json_stringify(error)} }
        }
        return agent_tool_handler_result("Checked resource inputs and project.", verdict)
      },
    },
  )
  reg = tool_define(
    reg,
    "add_standard_resource",
    "Create a standard resource module, dispatch tests and docs with exactly one string, integer and boolean field. Does not run Python tests or modify existing files.",
    {
      inputSchema: schema_to_json_schema(schema_of(Input)) + {additionalProperties: false},
      annotations: {kind: "edit", side_effect_level: "workspace_write"},
      handler: { args ->
        const input: Input = schema_expect(args, schema_of(Input))
        const files = prepare(fs, root, input)
        let changed: list<string> = []
        for file in files {
          const receipt = replace_text(
            fs,
            path_join(root, file.path),
            file.content,
            {create: true, overwrite: false},
          )
          require receipt.status == "created", "file creation failed"
          changed.push(file.path)
        }
        for file in files {
          require fs.read_text(path_join(root, file.path)) == file.content, "readback failed"
        }
        return agent_tool_handler_result(
          "Created resource module, dispatch tests and docs. Run python3 -m unittest discover -s tests.",
          {
            mutation_status: "applied",
            changed_paths: changed,
            verification: agent_tool_postcondition(changed),
          },
        )
      },
    },
  )
  return reg
}

pipeline default(harness: Harness) {
  harness.tools.mcp_tools(tools(harness.fs, harness.fs.cwd()))
}

