import { agent_dispatch_tool_call } from "std/agent/primitives"
import { agent_tool_postcondition, agent_tool_result_data } from "std/agent/tool_lifecycle"
import { with_temp_dir } from "std/testing"
import { identifier, render, tools } from "./server"

pipeline test_validation() {
  assert(identifier("reading_groups"))
  assert(!identifier("../escape"))
  assert(!identifier("id"))
  assert(!identifier("9items"))
  const files = render(
    {
      resource: "reading_groups",
      string_field: "display_name",
      integer_field: "member_count",
      boolean_field: "is_open",
    },
  )
  assert_eq(
    files.map({ f -> f.path }),
    ["app/resources/reading_groups.py", "tests/test_reading_groups.py", "docs/reading_groups.md"],
  )
  const module = files[0]
  assert(module != nil)
  assert_eq(
    module.content,
    "from threading import Lock\n\n\ndef mount(app):\n    records = []\n    lock = Lock()\n    fields = {\"display_name\": str, \"member_count\": int, \"is_open\": bool}\n\n    def create(payload):\n        if payload.keys() != fields.keys() or any(\n            type(payload[name]) is not expected for name, expected in fields.items()\n        ):\n            return 400, {\"error\": \"invalid_fields\"}\n        with lock:\n            record = {**payload, \"id\": len(records) + 1}\n            records.append(record)\n            return 201, record.copy()\n\n    def list_records(payload):\n        with lock:\n            return 200, [record.copy() for record in records]\n\n    app.route(\"POST\", \"/api/reading_groups\", create)\n    app.route(\"GET\", \"/api/reading_groups\", list_records)\n",
  )
}

pipeline test_dispatch(harness: Harness) {
  with_temp_dir(
    harness.fs,
    { root: string ->
      harness.fs.mkdir(path_join(root, "app/resources"))
      harness.fs.mkdir(path_join(root, "tests"))
      const host =
        "class App:\ndef route(\ndef dispatch(\nimportlib.import_module(f\"app.resources.{source.stem}\").mount(self)\nreturn 200, {\"status\": \"ok\"}\nreturn handler({} if payload is None else payload)\n"
      harness.fs.write_text(path_join(root, "app/http.py"), host)
      harness.fs.write_text(
        path_join(root, "app/resources/__init__.py"),
        "Resource modules export mount(app).",
      )
      const input = {
        resource: "reading_groups",
        string_field: "display_name",
        integer_field: "member_count",
        boolean_field: "is_open",
      }
      const reg = tools(harness.fs, root)
      const catalog = tool_schema(reg)
      assert_eq(len(catalog.tools), 2)
      for tool in catalog.tools {
        assert_eq(
          tool.inputSchema.required,
          ["resource", "string_field", "integer_field", "boolean_field"],
        )
        assert_eq(tool.inputSchema.additionalProperties, false)
      }
      const preflight = agent_dispatch_tool_call(
        harness.tools,
        {name: "check_standard_resource", arguments: input},
        reg,
      )
      assert(preflight.ok)
      assert_eq(agent_tool_result_data(preflight), {kind: "ready"})
      for file in render(input) {
        assert(!harness.fs.exists(path_join(root, file.path)))
      }
      const result = agent_dispatch_tool_call(
        harness.tools,
        {name: "add_standard_resource", arguments: input},
        reg,
      )
      assert(result.ok, result.error?.message ?? "dispatch failed")
      const data = agent_tool_result_data(result)
      const paths = [
        "app/resources/reading_groups.py",
        "tests/test_reading_groups.py",
        "docs/reading_groups.md",
      ]
      assert_eq(data.mutation_status, "applied")
      assert_eq(data.changed_paths, paths)
      assert_eq(data.verification, agent_tool_postcondition(paths))
      for file in render(input) {
        assert_eq(harness.fs.read_text(path_join(root, file.path)), file.content)
      }
      assert_eq(harness.fs.read_text(path_join(root, "app/http.py")), host)
      const duplicate = agent_dispatch_tool_call(
        harness.tools,
        {name: "add_standard_resource", arguments: input},
        reg,
      )
      assert(!duplicate.ok)
      const declined = agent_dispatch_tool_call(
        harness.tools,
        {name: "check_standard_resource", arguments: input},
        reg,
      )
      assert(declined.ok)
      assert_eq(agent_tool_result_data(declined).kind, "declined")
      for file in render(input) {
        assert_eq(harness.fs.read_text(path_join(root, file.path)), file.content)
      }
      const bad = agent_dispatch_tool_call(
        harness.tools,
        {
          name: "add_standard_resource",
          arguments: {
            resource: "escape",
            string_field: "id",
            integer_field: "count",
            boolean_field: "active",
          },
        },
        reg,
      )
      assert(!bad.ok)
      const overlap = agent_dispatch_tool_call(
        harness.tools,
        {
          name: "add_standard_resource",
          arguments: {
            resource: "overlap",
            string_field: "same",
            integer_field: "same",
            boolean_field: "active",
          },
        },
        reg,
      )
      assert(!overlap.ok)
      const unsupported = agent_dispatch_tool_call(
        harness.tools,
        {
          name: "add_standard_resource",
          arguments: {
            resource: "persistent",
            string_field: "name",
            integer_field: "count",
            boolean_field: "active",
            storage: "sqlite",
          },
        },
        reg,
      )
      assert(!unsupported.ok)
      for r in ["escape", "overlap", "persistent"] {
        for p in ["app/resources/${r}.py", "tests/test_${r}.py", "docs/${r}.md"] {
          assert(!harness.fs.exists(path_join(root, p)))
        }
      }
      harness.fs.write_text(path_join(root, "app/http.py"), "changed host")
      const stale = agent_dispatch_tool_call(
        harness.tools,
        {
          name: "add_standard_resource",
          arguments: {
            resource: "others",
            string_field: "name",
            integer_field: "count",
            boolean_field: "active",
          },
        },
        reg,
      )
      assert(!stale.ok)
      for p in ["app/resources/others.py", "tests/test_others.py", "docs/others.md"] {
        assert(!harness.fs.exists(path_join(root, p)))
      }
    },
  )
}
